
import type { Banner } from './Banner.js';
import type { Image } from './Image.js';
import type { NextAction } from './NextAction.js';
import type { PostalAddress } from './PostalAddress.js';

export type Merchant = { "address"?: PostalAddress; /** Default API version for requests without a Flint-Version header. Shared across live and test environments. */ "api_version"?: string; /** When the merchant's default API version last changed. Format: date-time. */ "api_version_changed_at"?: string; /** When the merchant's default API version was first set. Format: date-time. */ "api_version_pinned_at"?: string; /** Previous API version, present while a supported rollback is available. */ "api_version_previous"?: string; /** When the 72-hour rollback offer expires. Explicit changes to any supported version remain available afterward. Format: date-time. */ "api_version_rollback_expires_at"?: string; "banners"?: Array<Banner>; /** Business name buyers see on checkout, payment links, and receipts. Once the merchant starts verification, it stays in sync with the business name on the live Stripe account: a change on either side applies, and the latest change wins. */ "business_name"?: string; /** Flint-normalized business profile type. Unknown backend/provider values are returned as unknown. */ "business_type"?: "individual" | "company" | "non_profit" | "government_entity" | "unknown" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "current_deadline_at"?: string; "email": string; /** Whether Flint's synced readiness projection has past-due account requirements. */ "has_past_due": boolean; "logo"?: Image; "merchant_id": string; "metadata"?: Record<string, string>; /** RFC3339 timestamp. Format: date-time. */ "observed_at": string; /** Activation lifecycle status. A merchant can remain completed after activation while later readiness fields or requirements show current account attention is needed. */ "onboarding_status": "not_started" | "in_progress" | "completed" | (string & {}); "organization"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "name": string; "organization_id": string; "parent_organization_id"?: string; "status": "active" | "deleted" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "organization_id"?: string; "payments": { "next_actions": Array<NextAction>; "status": "ready" | "blocked" | "pending" | "not_available" | "not_requested" | (string & {}); "status_reason"?: "requirements_due" | "requirements_past_due" | "pending_verification" | "disabled_by_platform_policy" | "service_unavailable" | "onboarding_not_started" | null | (string & {}) | null; }; "payouts": { "next_actions": Array<NextAction>; "status": "ready" | "blocked" | "pending" | "not_available" | "not_requested" | (string & {}); "status_reason"?: "requirements_due" | "requirements_past_due" | "pending_verification" | "disabled_by_platform_policy" | "service_unavailable" | "onboarding_not_started" | null | (string & {}) | null; }; "phone"?: string; "reporting_timezone"?: string; "requirements": { /** RFC3339 timestamp. Format: date-time. */ "current_deadline_at"?: string; "currently_due": Array<string>; "disabled_reason"?: "account_attention_required" | "account_paused" | "account_rejected" | "account_requirements_due" | "account_under_review" | "requirements_past_due" | "requirements_pending_verification" | null | (string & {}) | null; "eventually_due": Array<string>; "past_due": Array<string>; "pending_verification": Array<string>; }; "status": "active" | "suspended" | "restricted" | "closed" | (string & {}); "status_reason"?: string; "support_email"?: string; "support_phone"?: string; "support_url"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Profile version. Changes made through Flint to the business name, contact details, metadata, organization, support details, or logo advance this version. Readiness updates and business names synced from Stripe do not. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "version": string; "website_url"?: string; };
